            }
            if (FormLinkInformation.TryFactory(obj.AttackRace, out var AttackRaceInfo))
            {
                yield return AttackRaceInfo;
            }
            if (FormLinkInformation.TryFactory(obj.BodyPartData, out var BodyPartDataInfo))
            {
                yield return BodyPartDataInfo;
            }
            if (FormLinkInformation.TryFactory(obj.DefaultHairColor, out var DefaultHairColorInfo))
            {
                yield return DefaultHairColorInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            if (obj.Model2 is {} Model2Items)
            {
                foreach (var item in Model2Items.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
